```go
// pipeline.go
package review

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
)

// envFakePipeline swaps the model-backed provider for a deterministic stub
// (spec §13). Mirrors the ENTIRE_TEST_*/Vogon convention.
const envFakePipeline = "ENTIRE_REVIEW_FAKE_PIPELINE"

// AgentOutput is one reviewer's prose narrative for the run.
type AgentOutput struct {
	Agent  string
	Output string
}

// StructureInput is the find→verify seam input (spec §5a).
type StructureInput struct {
	Agents       []AgentOutput
	DiffContext  string // file paths + hunk headers in scope
	ScopeBaseRef string
}

// StructuredReview is the structuring output: typed findings + a one-paragraph verdict.
type StructuredReview struct {
	Findings  []Finding
	Synthesis string
}

// PipelineProvider turns reviewer prose into structured findings + synthesis.
type PipelineProvider interface {
	Structure(ctx context.Context, in StructureInput) (StructuredReview, error)
}

// textGenPipelineProvider is the real provider: it composes a strict-JSON prompt
// and calls a text generator (the same seam lazySynthesisProvider uses).
type textGenPipelineProvider struct {
	gen func(ctx context.Context, prompt string) (string, error)
}

// rawStructure is the wire shape we ask the model to emit.
type rawStructure struct {
	Synthesis string `json:"synthesis"`
	Findings  []struct {
		File       string `json:"file"`
		Line       int    `json:"line"`
		Severity   string `json:"severity"`
		Category   string `json:"category"`
		Title      string `json:"title"`
		Detail     string `json:"detail"`
		Suggestion string `json:"suggestion"`
	} `json:"findings"`
}

func (p *textGenPipelineProvider) Structure(ctx context.Context, in StructureInput) (StructuredReview, error) {
	out, err := p.gen(ctx, composeStructurePrompt(in))
	if err != nil {
		return degradeToRaw(in), nil // never hard-fail a review (spec §5a)
	}
	var raw rawStructure
	if jsonErr := json.Unmarshal([]byte(extractJSON(out)), &raw); jsonErr != nil || len(raw.Findings) == 0 {
		return degradeToRaw(in), nil
	}
	files := diffFileSet(in.DiffContext)
	rev := StructuredReview{Synthesis: strings.TrimSpace(raw.Synthesis)}
	for _, rf := range raw.Findings {
		agent := primaryAgent(in)
		sev := normalizeSeverity(rf.Severity)
		cat := normalizeCategory(rf.Category)
		line := rf.Line
		if rf.File == "" || !files[rf.File] { // not in diff → file-level / not anchorable
			line = 0
		}
		id := computeFindingID(rf.File, enclosingSymbolFor(in.DiffContext, rf.File, line), rf.Title)
		if id == "" || (rf.File == "" && line == 0) {
			id = fallbackFindingID(rf.File, cat, rf.Title)
		}
		rev.Findings = append(rev.Findings, Finding{
			ID: id, File: rf.File, Line: line, Severity: sev, Category: cat,
			Title: strings.TrimSpace(rf.Title), Detail: strings.TrimSpace(rf.Detail),
			Suggestion: strings.TrimSpace(rf.Suggestion), Agent: agent,
		})
	}
	return rev, nil
}

// degradeToRaw emits exactly one raw-prose finding (spec §5a degrade rule).
func degradeToRaw(in StructureInput) StructuredReview {
	var b strings.Builder
	for _, a := range in.Agents {
		b.WriteString(a.Output)
		b.WriteString("\n")
	}
	prose := strings.TrimSpace(b.String())
	return StructuredReview{
		Synthesis: "",
		Findings: []Finding{{
			ID: fallbackFindingID("", CategoryOther, "Review output"),
			Severity: SeverityMedium, Category: CategoryOther,
			Title: "Review output", Detail: prose, Agent: primaryAgent(in),
		}},
	}
}

// fakePipelineProvider is the deterministic canary stub (no model call).
type fakePipelineProvider struct{}

func (fakePipelineProvider) Structure(_ context.Context, in StructureInput) (StructuredReview, error) {
	agent := primaryAgent(in)
	f := Finding{
		File: "review_target.go", Line: 1, Severity: SeverityMedium, Category: CategoryCorrectness,
		Title: "vogon canary finding", Detail: "deterministic finding for the canary",
		Suggestion: "no-op", Agent: agent,
	}
	f.ID = computeFindingID(f.File, "", f.Title)
	return StructuredReview{Synthesis: "Canary synthesis: 1 finding.", Findings: []Finding{f}}, nil
}

// pipelineProviderFor returns the fake when ENTIRE_REVIEW_FAKE_PIPELINE is set,
// else the supplied real provider.
func pipelineProviderFor(real PipelineProvider) PipelineProvider {
	if isFakePipelineEnabled() {
		return fakePipelineProvider{}
	}
	return real
}

func isFakePipelineEnabled() bool { return strings.TrimSpace(osGetenv(envFakePipeline)) != "" }

// --- helpers (small, pure; unit-tested via the provider tests) ---

func primaryAgent(in StructureInput) string {
	if len(in.Agents) > 0 { return in.Agents[0].Agent }
	return ""
}

func normalizeSeverity(s string) Severity {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "blocker", "critical", "high":
		return SeverityHigh
	case "medium", "med":
		return SeverityMedium
	default:
		return SeverityLow
	}
}

func normalizeCategory(c string) Category {
	switch Category(strings.ToLower(strings.TrimSpace(c))) {
	case CategorySecurity, CategoryCorrectness, CategoryPerformance, CategoryTests, CategoryDesign, CategoryReadability:
		return Category(strings.ToLower(strings.TrimSpace(c)))
	default:
		return CategoryOther
	}
}

// diffFileSet returns the set of repo-relative file paths present in the diff context.
func diffFileSet(diffContext string) map[string]bool {
	set := map[string]bool{}
	for _, ln := range strings.Split(diffContext, "\n") {
		ln = strings.TrimSpace(ln)
		if ln != "" && !strings.HasPrefix(ln, "@@") {
			set[ln] = true
		}
	}
	return set
}

// enclosingSymbolFor extracts the enclosing function/decl from the hunk header
// for file at line, from the diff context (git provides `@@ … @@ func Foo`).
// Returns "" when unavailable. (Minimal heuristic; refined in a later PR if needed.)
func enclosingSymbolFor(diffContext, file string, line int) string {
	_ = file; _ = line
	for _, ln := range strings.Split(diffContext, "\n") {
		if i := strings.LastIndex(ln, "@@"); i >= 0 && i+2 < len(ln) {
			return strings.TrimSpace(ln[i+2:])
		}
	}
	return ""
}

// extractJSON returns the first {...} block, tolerating leading prose/code fences.
func extractJSON(s string) string {
	start := strings.IndexByte(s, '{')
	end := strings.LastIndexByte(s, '}')
	if start < 0 || end <= start {
		return s
	}
	return s[start : end+1]
}

func composeStructurePrompt(in StructureInput) string {
	var b strings.Builder
	b.WriteString("You are converting code-review notes into structured findings. ")
	b.WriteString("Return ONLY a JSON object: {\"synthesis\":\"<one paragraph>\",\"findings\":[")
	b.WriteString("{\"file\":\"<repo-relative path from the diff>\",\"line\":<int or 0>,")
	b.WriteString("\"severity\":\"high|medium|low\",\"category\":\"security|correctness|performance|tests|design|readability|other\",")
	b.WriteString("\"title\":\"<one line>\",\"detail\":\"<why>\",\"suggestion\":\"<optional fix>\"}]}. ")
	b.WriteString("One object per distinct issue. No prose outside the JSON.\n\n## Diff in scope\n")
	b.WriteString(in.DiffContext)
	for _, a := range in.Agents {
		fmt.Fprintf(&b, "\n\n## Reviewer %s\n%s", a.Agent, a.Output)
	}
	return b.String()
}
```

