package review

import (
	"context"
	"testing"
)

// stubTextGen lets us drive the real provider's parse/degrade logic without a model.
type stubTextGen struct {
	out string
	err error
}

func (s stubTextGen) generate(_ context.Context, _ string) (string, error) { return s.out, s.err }

func TestStructure_ParsesStrictJSON(t *testing.T) {
	t.Parallel()
	jsonOut := `{"synthesis":"Recommend changes.","findings":[
	  {"file":"auth.go","line":42,"severity":"high","category":"security",
	   "title":"non-constant-time compare","detail":"==","suggestion":"use subtle"}]}`
	p := &textGenPipelineProvider{gen: stubTextGen{out: jsonOut}.generate}
	got, err := p.Structure(context.Background(), StructureInput{
		Agents:      []AgentOutput{{Agent: "codex", Output: "..."}},
		DiffContext: "auth.go\n@@ func check @@",
	})
	if err != nil {
		t.Fatal(err)
	}
	if got.Synthesis == "" || len(got.Findings) != 1 {
		t.Fatalf("got %+v", got)
	}
	f := got.Findings[0]
	if f.Severity != SeverityHigh || f.Category != CategorySecurity || f.Agent != "codex" || f.ID == "" {
		t.Fatalf("finding not populated: %+v", f)
	}
}

func TestStructure_DegradesToRawFindingOnParseFailure(t *testing.T) {
	t.Parallel()
	p := &textGenPipelineProvider{gen: stubTextGen{out: "my analysis: looks fine"}.generate}
	got, err := p.Structure(context.Background(), StructureInput{
		Agents: []AgentOutput{{Agent: "codex", Output: "my analysis: looks fine"}},
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Findings) != 1 || got.Findings[0].Category != CategoryOther || got.Findings[0].Line != 0 {
		t.Fatalf("expected one raw-prose finding, got %+v", got.Findings)
	}
}

func TestStructure_DropsUnknownFileToFileLevel(t *testing.T) {
	t.Parallel()
	jsonOut := `{"synthesis":"x","findings":[{"file":"ghost.go","line":9,"severity":"low",
	  "category":"bogus","title":"t","detail":"d"}]}`
	p := &textGenPipelineProvider{gen: stubTextGen{out: jsonOut}.generate}
	got, _ := p.Structure(context.Background(), StructureInput{DiffContext: "auth.go"})
	if got.Findings[0].Line != 0 {
		t.Fatal("file not in diff → Line must be 0")
	}
	if got.Findings[0].Category != CategoryOther {
		t.Fatal("unknown category → other")
	}
}

func TestFakePipelineProvider_Deterministic(t *testing.T) {
	t.Parallel()
	in := StructureInput{Agents: []AgentOutput{{Agent: "vogon", Output: "anything"}}}
	a, _ := fakePipelineProvider{}.Structure(context.Background(), in)
	b, _ := fakePipelineProvider{}.Structure(context.Background(), in)
	if len(a.Findings) == 0 || a.Synthesis == "" {
		t.Fatal("fake must yield findings + synthesis")
	}
	if a.Findings[0].ID != b.Findings[0].ID {
		t.Fatal("fake must be deterministic")
	}
}

func TestPipelineProviderFor_SelectsFakeViaEnv(t *testing.T) {
	t.Setenv(envFakePipeline, "1")
	if _, ok := pipelineProviderFor(nil).(fakePipelineProvider); !ok {
		t.Fatal("ENTIRE_REVIEW_FAKE_PIPELINE=1 must select the fake provider")
	}
}

