package review

import (
	"context"
	"strings"
	"testing"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

func TestStructureFindings_FromProvider(t *testing.T) {
	t.Parallel()
	summary := reviewtypes.RunSummary{AgentRuns: []reviewtypes.AgentRun{{
		Name:   "vogon",
		Status: reviewtypes.AgentStatusSucceeded,
		Buffer: []reviewtypes.Event{reviewtypes.AssistantText{Text: "some review prose"}},
	}}}
	findings, syn := structureFindings(context.Background(), fakePipelineProvider{}, summary, "")
	if len(findings) == 0 || syn == "" {
		t.Fatalf("want findings + synthesis, got %d findings / synthesis %q", len(findings), syn)
	}
}

func TestStructureFindings_NilProviderYieldsNothing(t *testing.T) {
	t.Parallel()
	findings, syn := structureFindings(context.Background(), nil, reviewtypes.RunSummary{
		AgentRuns: []reviewtypes.AgentRun{{Name: "x", Buffer: []reviewtypes.Event{reviewtypes.AssistantText{Text: "y"}}}},
	}, "")
	if len(findings) != 0 || syn != "" {
		t.Fatal("nil provider must yield no findings and no synthesis")
	}
}

func TestRenderReviewResults_ShowsSynthesisCountsAndFindings(t *testing.T) {
	t.Parallel()
	m := LocalReviewManifest{
		Synthesis: "Recommend changes.",
		Findings: []Finding{
			{Severity: SeverityHigh, File: "auth.go", Line: 42, Title: "timing", Agent: "codex"},
			{Severity: SeverityLow, File: "c.go", Line: 9, Title: "nit", Agent: "claude"},
		},
	}
	var b strings.Builder
	renderReviewResults(&b, m)
	out := b.String()
	for _, want := range []string{"Recommend changes.", "2 findings", "1 high", "auth.go:42", "timing"} {
		if !strings.Contains(out, want) {
			t.Fatalf("output missing %q:\n%s", want, out)
		}
	}
}

