// TestReviewPipeline_RunThenStructure_NoAPI exercises the full single-agent
// chain that PR #1 adds: a reviewer run produces a RunSummary whose buffer holds
// the reviewer's prose, and the structuring pass turns that into typed findings
// + a synthesis. The fake PipelineProvider makes structuring deterministic with
// zero model calls (the ENTIRE_REVIEW_FAKE_PIPELINE / canary contract, spec §13).
func TestReviewPipeline_RunThenStructure_NoAPI(t *testing.T) {
	t.Parallel()
	events := []reviewtypes.Event{
		reviewtypes.Started{},
		reviewtypes.AssistantText{Text: "HIGH auth.go:42 non-constant-time token compare"},
		reviewtypes.Finished{Success: true},
	}
	reviewer := &stubReviewer{name: "vogon", events: events}

	summary, err := Run(context.Background(), reviewer, reviewtypes.RunConfig{}, nil)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}
	if len(summary.AgentRuns) != 1 {
		t.Fatalf("expected 1 agent run, got %d", len(summary.AgentRuns))
	}

	findings, synthesis := structureFindings(context.Background(), fakePipelineProvider{}, summary, "auth.go")
	if len(findings) == 0 || synthesis == "" {
		t.Fatalf("expected structured findings + synthesis, got %d findings / synthesis %q", len(findings), synthesis)
	}
	if findings[0].Agent != "vogon" {
		t.Fatalf("finding should be attributed to the finder, got %q", findings[0].Agent)
	}
	if findings[0].ID == "" {
		t.Fatal("structured finding must carry a stable ID")
	}
}

