// finding (spec §4). It mirrors review.Finding's JSON tags exactly so the two
// packages stay decoupled (review owns the canonical type; checkpoint can't
// import review without cycling). Populated by unmarshaling
// session.State.ReviewFindingsJSON during condensation.
//

type ReviewFinding struct {
	ID         string  `json:"id"`
	File       string  `json:"file"`
	Line       int     `json:"line"`
	Severity   string  `json:"severity"`
	Category   string  `json:"category"`
	Title      string  `json:"title"`
	Detail     string  `json:"detail"`
	Suggestion string  `json:"suggestion,omitempty"`
	Agent      string  `json:"agent"`
	Confidence float64 `json:"confidence,omitempty"`
}

// ReviewCounts tallies review findings by severity for a checkpoint.
type ReviewCounts struct {
	High   int `json:"high"`
	Medium int `json:"medium"`
	Low    int `json:"low"`
}

// reviewCountsFrom tallies findings by severity, returning nil when empty so
// the summary's ReviewCounts stays absent for non-review checkpoints.
func reviewCountsFrom(findings []ReviewFinding) *ReviewCounts {
	if len(findings) == 0 {
		return nil
	}
	var c ReviewCounts
	for _, f := range findings {
		switch f.Severity {
		case "high":
			c.High++
		case "medium":
			c.Medium++
		default:
			c.Low++
		}
	}
	return &c
}

